class Employee extends DataClass implements Insertable<Employee> {
  final int id;
  final int workspaceId;
  final String employeeCode;
  final String name;
  final String phone;
  final String? email;
  final String role;
  final String designation;
  final String department;
  final String loginPin;
  final double baseSalary;
  final DateTime joiningDate;
  final bool isActive;
  final DateTime createdAt;
  const Employee(
      {required this.id,
      required this.workspaceId,
      required this.employeeCode,
      required this.name,
      required this.phone,
      this.email,
      required this.role,
      required this.designation,
      required this.department,
      required this.loginPin,
      required this.baseSalary,
      required this.joiningDate,
      required this.isActive,
      required this.createdAt});
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<int>(id);
    map['workspace_id'] = Variable<int>(workspaceId);
    map['employee_code'] = Variable<String>(employeeCode);
    map['name'] = Variable<String>(name);
    map['phone'] = Variable<String>(phone);
    if (!nullToAbsent || email != null) {
      map['email'] = Variable<String>(email);
    }
    map['role'] = Variable<String>(role);
    map['designation'] = Variable<String>(designation);
    map['department'] = Variable<String>(department);
    map['login_pin'] = Variable<String>(loginPin);
    map['base_salary'] = Variable<double>(baseSalary);
    map['joining_date'] = Variable<DateTime>(joiningDate);
    map['is_active'] = Variable<bool>(isActive);
    map['created_at'] = Variable<DateTime>(createdAt);
    return map;
  }

  EmployeesCompanion toCompanion(bool nullToAbsent) {
    return EmployeesCompanion(
      id: Value(id),
      workspaceId: Value(workspaceId),
      employeeCode: Value(employeeCode),
      name: Value(name),
      phone: Value(phone),
      email:
          email == null && nullToAbsent ? const Value.absent() : Value(email),
      role: Value(role),
      designation: Value(designation),
      department: Value(department),
      loginPin: Value(loginPin),
      baseSalary: Value(baseSalary),
      joiningDate: Value(joiningDate),
      isActive: Value(isActive),
      createdAt: Value(createdAt),
    );
  }

  factory Employee.fromJson(Map<String, dynamic> json,
      {ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return Employee(
      id: serializer.fromJson<int>(json['id']),
      workspaceId: serializer.fromJson<int>(json['workspaceId']),
      employeeCode: serializer.fromJson<String>(json['employeeCode']),
      name: serializer.fromJson<String>(json['name']),
      phone: serializer.fromJson<String>(json['phone']),
      email: serializer.fromJson<String?>(json['email']),
      role: serializer.fromJson<String>(json['role']),
      designation: serializer.fromJson<String>(json['designation']),
      department: serializer.fromJson<String>(json['department']),
      loginPin: serializer.fromJson<String>(json['loginPin']),
      baseSalary: serializer.fromJson<double>(json['baseSalary']),
      joiningDate: serializer.fromJson<DateTime>(json['joiningDate']),
      isActive: serializer.fromJson<bool>(json['isActive']),
      createdAt: serializer.fromJson<DateTime>(json['createdAt']),
    );
  }
  @override
  Map<String, dynamic> toJson({ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return <String, dynamic>{
      'id': serializer.toJson<int>(id),
      'workspaceId': serializer.toJson<int>(workspaceId),
      'employeeCode': serializer.toJson<String>(employeeCode),
      'name': serializer.toJson<String>(name),
