  final String name;
  final String? phone;
  final String? notes;
  final String? gstin;
  final String? address;
  final double balance;
  final double creditLimit;
  const Customer(
      {required this.id,
      this.workspaceId,
      required this.name,
      this.phone,
      this.notes,
      this.gstin,
      this.address,
      required this.balance,
      required this.creditLimit});
