              $$SuppliersTableOrderingComposer($db: db, $table: table),
          createComputedFieldComposer: () =>
              $$SuppliersTableAnnotationComposer($db: db, $table: table),
          updateCompanionCallback: ({
            Value<int> id = const Value.absent(),
            Value<int?> workspaceId = const Value.absent(),
            Value<String> name = const Value.absent(),
            Value<String?> phone = const Value.absent(),
            Value<String?> gstin = const Value.absent(),
            Value<String?> address = const Value.absent(),
            Value<double> balance = const Value.absent(),
          }) =>
              SuppliersCompanion(
            id: id,
            workspaceId: workspaceId,
            name: name,
            phone: phone,
            gstin: gstin,
            address: address,
            balance: balance,
          ),
          createCompanionCallback: ({
            Value<int> id = const Value.absent(),
            Value<int?> workspaceId = const Value.absent(),
            required String name,
            Value<String?> phone = const Value.absent(),
            Value<String?> gstin = const Value.absent(),
            Value<String?> address = const Value.absent(),
            Value<double> balance = const Value.absent(),
          }) =>
              SuppliersCompanion.insert(
            id: id,
            workspaceId: workspaceId,
            name: name,
            phone: phone,
            gstin: gstin,
            address: address,
            balance: balance,
          ),
          withReferenceMapper: (p0) => p0
              .map((e) => (
                    e.readTable(table),
                    $$SuppliersTableReferences(db, table, e)
                  ))
              .toList(),
          prefetchHooksCallback: (
              {workspaceId = false,
              purchaseInvoicesRefs = false,
              stockMovementsRefs = false,
              purchasesRefs = false}) {
            return PrefetchHooks(
              db: db,
              explicitlyWatchedTables: [
                if (purchaseInvoicesRefs) db.purchaseInvoices,
                if (stockMovementsRefs) db.stockMovements,
                if (purchasesRefs) db.purchases
              ],
              addJoins: <
                  T extends TableManagerState<
                      dynamic,
                      dynamic,
                      dynamic,
                      dynamic,
                      dynamic,
                      dynamic,
                      dynamic,
                      dynamic,
                      dynamic,
                      dynamic,
                      dynamic>>(state) {
                if (workspaceId) {
                  state = state.withJoin(
                    currentTable: table,
                    currentColumn: table.workspaceId,
                    referencedTable:
                        $$SuppliersTableReferences._workspaceIdTable(db),
                    referencedColumn:
                        $$SuppliersTableReferences._workspaceIdTable(db).id,
                  ) as T;
                }

                return state;
              },
              getPrefetchedDataCallback: (items) async {
