        bool deliveryOrderItemsRefs,
        bool stockMovementsRefs,
        bool purchasesRefs,
        bool saleItemsRefs})> {
  $$ProductsTableTableManager(_$AppDatabase db, $ProductsTable table)
      : super(TableManagerState(
          db: db,
          table: table,
          createFilteringComposer: () =>
              $$ProductsTableFilterComposer($db: db, $table: table),
          createOrderingComposer: () =>
              $$ProductsTableOrderingComposer($db: db, $table: table),
          createComputedFieldComposer: () =>
              $$ProductsTableAnnotationComposer($db: db, $table: table),
          updateCompanionCallback: ({
            Value<int> id = const Value.absent(),
            Value<int?> workspaceId = const Value.absent(),
            Value<String> name = const Value.absent(),
            Value<String> sku = const Value.absent(),
            Value<String?> barcode = const Value.absent(),
            Value<int?> categoryId = const Value.absent(),
            Value<double> cost = const Value.absent(),
            Value<double> price = const Value.absent(),
            Value<int> stockQty = const Value.absent(),
            Value<int> lowStockThreshold = const Value.absent(),
            Value<String> unit = const Value.absent(),
            Value<String?> notes = const Value.absent(),
            Value<String?> imagePath = const Value.absent(),
            Value<String?> hsnCode = const Value.absent(),
            Value<double> gstRate = const Value.absent(),
            Value<DateTime> createdAt = const Value.absent(),
            Value<DateTime> updatedAt = const Value.absent(),
          }) =>
              ProductsCompanion(
            id: id,
            workspaceId: workspaceId,
            name: name,
            sku: sku,
            barcode: barcode,
            categoryId: categoryId,
            cost: cost,
            price: price,
            stockQty: stockQty,
            lowStockThreshold: lowStockThreshold,
            unit: unit,
            notes: notes,
            imagePath: imagePath,
            hsnCode: hsnCode,
            gstRate: gstRate,
            createdAt: createdAt,
            updatedAt: updatedAt,
          ),
          createCompanionCallback: ({
            Value<int> id = const Value.absent(),
            Value<int?> workspaceId = const Value.absent(),
            required String name,
            required String sku,
            Value<String?> barcode = const Value.absent(),
            Value<int?> categoryId = const Value.absent(),
            required double cost,
            required double price,
            required int stockQty,
            Value<int> lowStockThreshold = const Value.absent(),
            Value<String> unit = const Value.absent(),
            Value<String?> notes = const Value.absent(),
            Value<String?> imagePath = const Value.absent(),
            Value<String?> hsnCode = const Value.absent(),
            Value<double> gstRate = const Value.absent(),
            Value<DateTime> createdAt = const Value.absent(),
            Value<DateTime> updatedAt = const Value.absent(),
          }) =>
              ProductsCompanion.insert(
            id: id,
            workspaceId: workspaceId,
            name: name,
            sku: sku,
            barcode: barcode,
            categoryId: categoryId,
            cost: cost,
            price: price,
            stockQty: stockQty,
            lowStockThreshold: lowStockThreshold,
            unit: unit,
            notes: notes,
            imagePath: imagePath,
            hsnCode: hsnCode,
            gstRate: gstRate,
            createdAt: createdAt,
            updatedAt: updatedAt,
          ),
          withReferenceMapper: (p0) => p0
              .map((e) =>
                  (e.readTable(table), $$ProductsTableReferences(db, table, e)))
              .toList(),
          prefetchHooksCallback: (
              {workspaceId = false,
              categoryId = false,
              purchaseInvoiceItemsRefs = false,
              incentiveRulesRefs = false,
              deliveryOrderItemsRefs = false,
              stockMovementsRefs = false,
              purchasesRefs = false,
              saleItemsRefs = false}) {
            return PrefetchHooks(
              db: db,
              explicitlyWatchedTables: [
                if (purchaseInvoiceItemsRefs) db.purchaseInvoiceItems,
                if (incentiveRulesRefs) db.incentiveRules,
                if (deliveryOrderItemsRefs) db.deliveryOrderItems,
                if (stockMovementsRefs) db.stockMovements,
                if (purchasesRefs) db.purchases,
                if (saleItemsRefs) db.saleItems
              ],
              addJoins: <
                  T extends TableManagerState<
                      dynamic,
                      dynamic,
                      dynamic,
                      dynamic,
                      dynamic,
                      dynamic,
                      dynamic,
                      dynamic,
                      dynamic,
                      dynamic,
                      dynamic>>(state) {
                if (workspaceId) {
                  state = state.withJoin(
                    currentTable: table,
                    currentColumn: table.workspaceId,
                    referencedTable:
                        $$ProductsTableReferences._workspaceIdTable(db),
                    referencedColumn:
                        $$ProductsTableReferences._workspaceIdTable(db).id,
                  ) as T;
                }
                if (categoryId) {
                  state = state.withJoin(
                    currentTable: table,
                    currentColumn: table.categoryId,
                    referencedTable:
                        $$ProductsTableReferences._categoryIdTable(db),
                    referencedColumn:
                        $$ProductsTableReferences._categoryIdTable(db).id,
                  ) as T;
                }

                return state;
              },
              getPrefetchedDataCallback: (items) async {
                return [
                  if (purchaseInvoiceItemsRefs)
                    await $_getPrefetchedData<Product, $ProductsTable,
                            PurchaseInvoiceItem>(
                        currentTable: table,
                        referencedTable: $$ProductsTableReferences
                            ._purchaseInvoiceItemsRefsTable(db),
                        managerFromTypedResult: (p0) =>
                            $$ProductsTableReferences(db, table, p0)
                                .purchaseInvoiceItemsRefs,
                        referencedItemsForCurrentItem:
                            (item, referencedItems) => referencedItems
                                .where((e) => e.productId == item.id),
                        typedResults: items),
                  if (incentiveRulesRefs)
                    await $_getPrefetchedData<Product, $ProductsTable,
                            IncentiveRule>(
                        currentTable: table,
                        referencedTable: $$ProductsTableReferences
                            ._incentiveRulesRefsTable(db),
                        managerFromTypedResult: (p0) =>
                            $$ProductsTableReferences(db, table, p0)
                                .incentiveRulesRefs,
                        referencedItemsForCurrentItem:
                            (item, referencedItems) => referencedItems
                                .where((e) => e.targetProductId == item.id),
                        typedResults: items),
                  if (deliveryOrderItemsRefs)
                    await $_getPrefetchedData<Product, $ProductsTable,
                            DeliveryOrderItem>(
                        currentTable: table,
