              {workspaceId = false,
              plotsRefs = false,
              leadsRefs = false,
              siteVisitsRefs = false}) {
            return PrefetchHooks(
              db: db,
              explicitlyWatchedTables: [
                if (plotsRefs) db.plots,
                if (leadsRefs) db.leads,
                if (siteVisitsRefs) db.siteVisits
