                        referencedItemsForCurrentItem:
                            (item, referencedItems) => referencedItems
                                .where((e) => e.projectId == item.id),
                        typedResults: items),
                  if (leadsRefs)
                    await $_getPrefetchedData<Project, $ProjectsTable, Lead>(
                        currentTable: table,
                        referencedTable:
                            $$ProjectsTableReferences._leadsRefsTable(db),
                        managerFromTypedResult: (p0) =>
                            $$ProjectsTableReferences(db, table, p0).leadsRefs,
                        referencedItemsForCurrentItem:
                            (item, referencedItems) => referencedItems
                                .where((e) => e.interestedProjectId == item.id),
                        typedResults: items),
                  if (siteVisitsRefs)
                    await $_getPrefetchedData<Project, $ProjectsTable,
                            SiteVisit>(
                        currentTable: table,
                        referencedTable:
                            $$ProjectsTableReferences._siteVisitsRefsTable(db),
                        managerFromTypedResult: (p0) =>
                            $$ProjectsTableReferences(db, table, p0)
